grid=[[8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,8,8,5,8,8,8,8,8,5,8,8],[8,5,5,8,8,8,8,8,5,8,8,5,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,5,8,8,8]]
h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
# Fill between consecutive 5 markers in each row and column.
for r in range(h):
 cs=[c for c,v in enumerate(grid[r]) if v==5]
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b): out[r][c]=3
for c in range(w):
 rs=[r for r in range(h) if grid[r][c]==5]
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b): out[r][c]=3
print('markers', [[(r,c) for c,v in enumerate(row) if v==5] for r,row in enumerate(grid)])
print('output')
for row in out: print(row)
print([len(r) for r in out])
